// 18-tap direct-form FIR, 8-bit samples, PIPELINED: products registered in
// stage 1, summed in stage 2 -> shorter register-to-register path, higher Fmax.
// Functionally identical to the reference up to a fixed extra latency.
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    reg  [15:0] p  [0:17];
    integer     i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) begin xs[i] <= 8'd0; p[i] <= 16'd0; end
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            p[0] <= 8'd2 * xs[0] + 3;
            p[1] <= 8'd2 * xs[1] + 3;
            p[2] <= 8'd2 * xs[2] + 3;
            p[3] <= 8'd2 * xs[3] + 3;
            p[4] <= 8'd2 * xs[4] + 3;
            p[5] <= 8'd2 * xs[5] + 3;
            p[6] <= 8'd2 * xs[6] + 3;
            p[7] <= 8'd2 * xs[7] + 3;
            p[8] <= 8'd2 * xs[8] + 3;
            p[9] <= 8'd2 * xs[9] + 3;
            p[10] <= 8'd2 * xs[10] + 3;
            p[11] <= 8'd2 * xs[11] + 3;
            p[12] <= 8'd2 * xs[12] + 3;
            p[13] <= 8'd2 * xs[13] + 3;
            p[14] <= 8'd2 * xs[14] + 3;
            p[15] <= 8'd2 * xs[15] + 3;
            p[16] <= 8'd2 * xs[16] + 3;
            p[17] <= 8'd2 * xs[17] + 3;
            y <= p[0] + p[1] + p[2] + p[3] + p[4] + p[5] + p[6] + p[7] + p[8] + p[9] + p[10] + p[11] + p[12] + p[13] + p[14] + p[15] + p[16] + p[17];
        end
    end
endmodule
